// Two things happen here on purpose BEFORE the model is asked:
// 1. An own keyword check for the typical Annex III areas. If the model later
//    proposes something milder than this heuristic, the mismatch becomes
//    visible - a model should not be the only safety net.
// 2. A stable report ID, so the inventory row, the escalation mail and the
//    later human review can all be matched to the same case.
const annexIII = [
  { category: 'Employment and worker management (Annex III No. 4)', terms: ['applicant', 'recruit', 'hiring', 'cv screening', 'resume screening', 'promotion', 'dismissal', 'performance review', 'employee rating', 'shift allocation'] },
  { category: 'Biometrics (Annex III No. 1)', terms: ['biometric', 'face recognition', 'facial recognition', 'fingerprint', 'emotion recognition', 'voice identification'] },
  { category: 'Creditworthiness and insurance (Annex III No. 5)', terms: ['creditworth', 'credit score', 'credit scoring', 'risk premium', 'insurance tariff', 'solvency'] },
  { category: 'Education and examination (Annex III No. 3)', terms: ['exam grading', 'grading', 'admission', 'student assessment', 'learning progress'] },
  { category: 'Critical infrastructure (Annex III No. 2)', terms: ['power grid', 'water supply', 'traffic control', 'critical infrastructure', 'gas network'] },
  { category: 'Access to essential services (Annex III No. 5)', terms: ['social benefit', 'emergency call', 'triage', 'eligibility check'] },
  { category: 'Law enforcement and migration (Annex III No. 6 and 7)', terms: ['law enforcement', 'police', 'asylum', 'migration', 'border control'] }
];

const out = [];
for (const entry of $input.all()) {
  const f = entry.json || {};
  const system = String(f['System / application'] || '').trim();
  const purpose = String(f['Purpose and area of use'] || '').trim();
  const dataTypes = String(f['Types of data processed'] || '').trim();
  const haystack = (system + ' ' + purpose + ' ' + dataTypes).toLowerCase();

  const hits = annexIII.filter(k => k.terms.some(t => haystack.includes(t))).map(k => k.category);

  const decisionImpact = String(f['Does the system influence decisions about people?'] || 'Unclear');
  const visibility = String(f['Is the output visible to people outside the company?'] || 'No, internal only');

  // External dialogue or AI output that leaves the company triggers the
  // transparency duty under Art. 50 - that is not a judgement call.
  const transparencyRelevant = visibility.startsWith('Yes');

  const serial = String(Date.now()).slice(-6);
  out.push({
    json: {
      report_id: 'AI-' + new Date().getFullYear() + '-' + serial,
      reported_on: new Date().toISOString().slice(0, 10),
      department: String(f['Department'] || '').trim(),
      contact: String(f['Contact (email)'] || '').trim(),
      system,
      vendor: String(f['Vendor'] || '').trim(),
      purpose,
      data_types: dataTypes,
      affected_groups: String(f['Affected groups of people'] || ''),
      legal_basis: String(f['Legal basis for the processing'] || ''),
      decision_impact: decisionImpact,
      visibility,
      transparency_relevant: transparencyRelevant,
      heuristic_annex_iii: hits.length > 0,
      heuristic_categories: hits.join('; '),
      legal_basis_unclear: String(f['Legal basis for the processing'] || '').startsWith('Unclear')
    }
  });
}
return out;

