parameters.jsCode:
// The proposal from the model is not copied into the inventory as is, it is
// checked first:
// 1. Only the four allowed classes pass. Anything else becomes
//    unclear_manual_review - a hallucinated class must never end up in the
//    inventory.
// 2. If the own keyword check points at Annex III but the model was milder,
//    the stricter assessment wins. Understating is the more expensive error.
// 3. Output that is visible outside the company triggers the transparency
//    duty under Art. 50, no matter what the model answered.
const ALLOWED = ['prohibited', 'high_risk_annex_iii', 'transparency_art_50', 'minimal_risk'];
const LABELS = {
  prohibited: 'Prohibited practice (Art. 5) - stop using the system now',
  high_risk_annex_iii: 'High risk under Annex III',
  transparency_art_50: 'Transparency obligation under Art. 50',
  minimal_risk: 'Minimal risk',
  unclear_manual_review: 'Unclear - manual review required'
};

const report = $('Normalize the report').item.json;
const v = $input.first().json.message?.content ?? $input.first().json;

let riskClass = String(v.risk_class || '').trim().toLowerCase();
const corrections = [];
if (!ALLOWED.includes(riskClass)) {
  corrections.push('The model returned an unknown class (' + (v.risk_class || 'empty') + ')');
  riskClass = 'unclear_manual_review';
}

if (report.heuristic_annex_iii && riskClass !== 'prohibited' && riskClass !== 'high_risk_annex_iii') {
  corrections.push('Keyword check points at Annex III (' + report.heuristic_categories + '), the proposal was raised');
  riskClass = 'high_risk_annex_iii';
}

if (report.transparency_relevant && riskClass === 'minimal_risk') {
  corrections.push('Output is visible outside the company - the transparency duty under Art. 50 applies on top');
  riskClass = 'transparency_art_50';
}

const obligations = Array.isArray(v.obligations) ? v.obligations.slice() : [];
if (report.transparency_relevant && !obligations.some(o => /disclos|label|transparen/i.test(String(o)))) {
  obligations.push('Disclose the use of AI and label AI generated content towards the people concerned (Art. 50)');
}
obligations.push('Make sure the people using the system have sufficient AI literacy (Art. 4, in force since 2025-02-02)');

const openQuestions = Array.isArray(v.open_questions) ? v.open_questions.slice() : [];
if (report.legal_basis_unclear) openQuestions.push('The legal basis of the processing is unresolved - clarify with the data protection officer');
if (String(report.decision_impact).startsWith('Unclear')) openQuestions.push('The effect on decisions about people is unresolved - walk through the process with the department');

const escalate = ['prohibited', 'high_risk_annex_iii', 'unclear_manual_review'].includes(riskClass);

return [{
  json: {
    ...report,
    risk_class: riskClass,
    risk_class_label: LABELS[riskClass],
    relevant_category: v.relevant_category || 'none',
    reasoning: v.reasoning || '',
    counter_argument: v.counter_argument || '',
    confidence: v.confidence || 'low',
    obligations: obligations.join(' | '),
    open_questions: openQuestions.join(' | '),
    deadline_note: v.deadline_note || 'Art. 4 and Art. 5 since 2025-02-02, Art. 50 and Annex III since 2026-08-02, Annex I from 2027-08-02',
    automatic_corrections: corrections.join(' | '),
    review_status: 'Proposal - human review pending',
    escalate
  }
}];

